// Normalización de transporte: cada proveedor de WhatsApp manda un shape
// distinto y acá se lo lleva al contrato del servicio de negociación.
// PROHIBIDO agregar lógica de dominio en este nodo (§4 del brief): si una
// decisión de negocio termina acá, se rechaza en review.
const salida = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  // Botmaker
  let telefono = b.contactId || b.platformContactId;
  let texto = b.message || b.messageText || b.text;
  let messageId = b.messageId || b.id;

  // Kapso / Meta Cloud API
  const kapso = b.data?.message || b.message;
  if (!telefono && kapso) {
    telefono = kapso.from;
    texto = kapso.text?.body ?? kapso.body ?? texto;
    messageId = kapso.id || messageId;
  }

  // WhatsApp Cloud API (payload crudo de Meta)
  const meta = b.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  if (!telefono && meta) {
    telefono = meta.from;
    texto = meta.text?.body ?? texto;
    messageId = meta.id || messageId;
  }

  salida.push({
    json: {
      telefono_e164: String(telefono || '').replace(/\D/g, ''),
      texto: String(texto || '').trim(),
      canal: b.canal || 'whatsapp',
      message_id: String(messageId || ''),
      procesable: Boolean(telefono && String(texto || '').trim()),
    },
  });
}

return salida;
